s=today.read_text(encoding='utf-8')

s=s.replace('  let libraryFilter = "all";\n','  let libraryFilter = "all";\n  let adoptingFreshCard = false;\n  const ADD_INTENT_KEY = "lexiflow:today-add-intent-v4";\n')

s=s.replace('  function primaryHtml(plan){\n', '''  function markTodayAddIntent(){\n    try{sessionStorage.setItem(ADD_INTENT_KEY,String(Date.now()));}catch{}\n  }\n  function todayAddIntentStartedAt(){\n    try{\n      const value=Number(sessionStorage.getItem(ADD_INTENT_KEY)||0);\n      if(!value||Date.now()-value>30*60*1000){sessionStorage.removeItem(ADD_INTENT_KEY);return 0;}\n      return value;\n    }catch{return 0;}\n  }\n  function clearTodayAddIntent(){try{sessionStorage.removeItem(ADD_INTENT_KEY);}catch{}}\n\n  function primaryHtml(plan){\n''')

s=s.replace('if(Number(plan.remainingSelectSlots||0)>0&&!(latestData?.cards||[]).length)return `<button class="btn primary" data-route="add">添加第一个单词</button>`;\n    if(Number(plan.remainingSelectSlots||0)>0)return `<button class="btn primary" data-route="add">继续添加新词</button>`;', 'if(Number(plan.remainingSelectSlots||0)>0&&!(latestData?.cards||[]).length)return `<button class="btn primary" data-route="add" data-tp-add-today="1">添加第一个单词</button>`;\n    if(Number(plan.remainingSelectSlots||0)>0)return `<button class="btn primary" data-route="add" data-tp-add-today="1">继续添加新词</button>`;')

s=s.replace('    if(save&&!document.querySelector(".study-card-focus")){setText(save,"保存到单词库");save.title="保存后会出现在单词库的“待学习”中，由你决定哪天加入 Today";}','    if(save&&!document.querySelector(".study-card-focus")){\n      if(todayAddIntentStartedAt()){setText(save,"保存并加入今日学习");save.title="保存后直接完成今日选词，下一学习日开始记忆";}\n      else{setText(save,"保存到单词库");save.title="保存后会进入待学习列表";}\n    }')

old='''  async function selectFromPending(id){\n    if(saving)return false;saving=true;\n    try{\n      await refresh();const next=core.normalizeData(JSON.parse(JSON.stringify(latestData||{}))), plan=next.dailyPlan;\n      if(Number(plan.remainingSelectSlots||0)<=0)return false;\n      const card=next.cards.find(item=>item.id===id);if(!card||card.stage!=="select"||!card.inboxPending)return false;\n      const now=new Date();card.inboxPending=false;card.todaySelectedOn=core.dayKey(now);card.stageEligibleOn=now.toISOString();card.inboxSelectedAt=now.toISOString();card.updatedAt=now.toISOString();\n      next.activities=Array.isArray(next.activities)?next.activities:[];next.activities.push({id:uid(),type:"library-selected",cardId:card.id,at:now.toISOString(),authority:"today-plan-v3"});\n      await persist(next,"library-selected");location.reload();return true;\n    }finally{saving=false;}\n  }\n'''
new='''  function completeSelection(next,card,now,source="library"){\n    const day=core.dayKey(now),prev={...card,learningStage:"select"};\n    card.inboxPending=false;\n    card.todaySelectedOn=day;\n    card.selectedOn=day;\n    card.inboxSelectedAt=now.toISOString();\n    card.selectCompletedOn=now.toISOString();\n    card.stage="memorize";\n    card.learningStage="memorize";\n    Object.assign(card,core.crossDayPatch(prev,{stage:"memorize",learningStage:"memorize"},now)||{});\n    card.updatedAt=now.toISOString();\n    next.activities=Array.isArray(next.activities)?next.activities:[];\n    next.activities.push({id:uid(),type:"library-selected",cardId:card.id,at:now.toISOString(),authority:"today-plan-v3",source});\n    next.activities.push({id:uid(),type:"stage-complete",cardId:card.id,stage:"select",nextStage:"memorize",at:now.toISOString(),authority:"today-plan-v3",source});\n  }\n\n  async function selectFromPending(id,source="library"){\n    if(saving)return false;saving=true;\n    try{\n      await refresh();const next=core.normalizeData(JSON.parse(JSON.stringify(latestData||{}))), plan=next.dailyPlan||core.buildDailyPlan(next);\n      if(Number(plan.remainingSelectSlots||0)<=0)return false;\n      const card=next.cards.find(item=>item.id===id);if(!card||core.canonicalStage(card)!=="select"||!card.inboxPending)return false;\n      const now=new Date();completeSelection(next,card,now,source);\n      await persist(next,source==="today-add"?"today-add-complete-select":"library-selected-complete-select");location.reload();return true;\n    }finally{saving=false;}\n  }\n\n  async function adoptFreshTodayCard(){\n    if(adoptingFreshCard||saving)return false;\n    const startedAt=todayAddIntentStartedAt();if(!startedAt)return false;\n    syncFromGateway();\n    const plan=latestData?.dailyPlan||core.buildDailyPlan(latestData||{});\n    if(Number(plan?.remainingSelectSlots||0)<=0){clearTodayAddIntent();return false;}\n    const card=(latestData?.cards||[])\n      .filter(item=>core.canonicalStage(item)==="select"&&item.inboxPending===true&&new Date(item.createdAt||0).getTime()>=startedAt-1000)\n      .sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0))[0];\n    if(!card)return false;\n    clearTodayAddIntent();adoptingFreshCard=true;\n    try{return await selectFromPending(card.id,"today-add");}\n    finally{adoptingFreshCard=false;}\n  }\n'''
if old not in s: raise SystemExit('selectFromPending anchor missing')
s=s.replace(old,new)

s=s.replace('''    const route=String(routeButton.dataset.route||"").trim();\n    if(!route)return false;\n''','''    const route=String(routeButton.dataset.route||"").trim();\n    if(!route)return false;\n    if(routeButton.dataset.tpAddToday==="1")markTodayAddIntent();\n''')

