s=s.replace('.lexi-select-v3-example{padding-top:11px;border-top:1px solid var(--line);line-height:1.65}.lexi-select-v3-example p{margin:4px 0 0;color:var(--muted)}', '.lexi-select-v3-example{padding-top:11px;border-top:1px solid var(--line);line-height:1.65}.lexi-select-v3-example-line{display:flex;align-items:flex-start;gap:8px}.lexi-select-v3-example-line>span{flex:1}.lexi-select-v3-example-line button{border:0;background:transparent;cursor:pointer;font-size:16px;line-height:1.4}.lexi-select-v3-example p{margin:4px 0 0;color:var(--muted)}')
s=s.replace('${card.exampleEn?`<div class="lexi-select-v3-example"><div>${esc(card.exampleEn)}</div>${card.exampleZh?`<p>${esc(card.exampleZh)}</p>`:""}</div>`:""}', '${card.exampleEn?`<div class="lexi-select-v3-example"><div class="lexi-select-v3-example-line"><span>${esc(card.exampleEn)}</span><button type="button" data-select-v3="speak-example" aria-label="播放例句">🔊</button></div>${card.exampleZh?`<p>${esc(card.exampleZh)}</p>`:""}</div>`:""}')
old='''  async function speak(){\n    const card=currentCard();if(!card)return;\n    try{if(typeof window.LexiFlowNaturalTts?.play==="function"&&await window.LexiFlowNaturalTts.play(card.word))return;}catch{}\n    try{const utterance=new SpeechSynthesisUtterance(card.word);utterance.lang="en-US";speechSynthesis.cancel();speechSynthesis.speak(utterance);}catch{}\n  }\n\n  document.addEventListener("click",event=>{\n    const button=event.target?.closest?.('[data-select-v3="speak"]');\n    if(!button)return;\n    event.preventDefault();event.stopImmediatePropagation();void speak();\n  },true);\n'''
new='''  async function playAudio(src){\n    return new Promise((resolve,reject)=>{const audio=new Audio(src);audio.onended=resolve;audio.onerror=reject;audio.play().catch(reject);});\n  }\n\n  async function speakWord(){\n    const card=currentCard();if(!card)return;\n    const segments=[];if(card.audioUrl)segments.push(card.audioUrl);if(Array.isArray(card.audioUrls))segments.push(...card.audioUrls);\n    if(segments.length){\n      try{for(const src of Array.from(new Set(segments.filter(Boolean))))await playAudio(src);return;}catch{}\n    }\n    try{if(typeof window.LexiFlowNaturalTts?.play==="function"&&await window.LexiFlowNaturalTts.play(card.word))return;}catch{}\n  }\n\n  async function speakExample(){\n    const card=currentCard();if(!card?.exampleEn)return;\n    try{if(typeof window.LexiFlowNaturalTts?.play==="function")await window.LexiFlowNaturalTts.play(card.exampleEn);}catch{}\n  }\n\n  document.addEventListener("click",event=>{\n    const button=event.target?.closest?.('[data-select-v3]');\n    if(!button)return;\n    const action=button.dataset.selectV3;if(action!=="speak"&&action!=="speak-example")return;\n    event.preventDefault();event.stopImmediatePropagation();\n    if(action==="speak")void speakWord();else void speakExample();\n  },true);\n'''
if old not in s: raise SystemExit('select speak anchor missing')
s=s.replace(old,new)
select.write_text(s,encoding='utf-8')

