s=s.replace('assert(source.includes("selectFromPending")&&source.includes("moveBackToPending"),"Word Library must explicitly own adding/removing Pending words from Today");', 'assert(source.includes("selectFromPending")&&source.includes("moveBackToPending"),"Word Library must explicitly own adding/removing Pending words from Today");\nassert(source.includes("function completeSelection(next,card,now"),"choosing a new word must complete Select in the same learner decision instead of requiring a second Today confirmation");\nassert(source.includes("card.stage=\\\"memorize\\\"")&&source.includes("core.crossDayPatch"),"completed selection must schedule Memorize for the next StudyDay");\nassert(source.includes("data-tp-add-today=\\\"1\\\"")&&source.includes("adoptFreshTodayCard"),"Today add flow must auto-adopt a freshly created card without a Word Library detour");')
